`timescale 1ns/1ps
module m9_pv_tb;parameter CASE_ID=1;parameter DATA_DIR="data";localparam R=32,K=128,N=4096;
 reg clk=0,rst_n=0,clear=0,iv=0,ordy=0;wire ir,ov,err;wire[383:0]out;wire[31:0]ic,oc,sc;reg[15:0]p16[0:N-1];reg[31:0]p32[0:N-1];reg[255:0]v16[0:N-1];reg[511:0]v32[0:N-1];reg[383:0]e16[0:R-1],e32[0:R-1],expected;integer cy=0,send=0,recv=0,mis=0,lastcy=0,maxrow=0,c,lane,diff,errsum=0,maxerr=0;reg signed[23:0]got,exp;
 generate if(CASE_ID==1)m9_fp16_pv d(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(iv),.in_ready(ir),.in_first_key(send%K==0),.in_last_key(send%K==K-1),.in_prob(p16[send]),.in_v(v16[send]),.out_valid(ov),.out_ready(ordy),.out_context16_s24(out),.input_key_count(ic),.output_row_count(oc),.saturation_count(sc),.error(err));else m9_fp32_pv d(.clk(clk),.rst_n(rst_n),.clear(clear),.in_valid(iv),.in_ready(ir),.in_first_key(send%K==0),.in_last_key(send%K==K-1),.in_prob(p32[send]),.in_v(v32[send]),.out_valid(ov),.out_ready(ordy),.out_context16_s24(out),.input_key_count(ic),.output_row_count(oc),.saturation_count(sc),.error(err));endgenerate
 always#3.3335 clk=~clk;initial begin $readmemh({DATA_DIR,"/prob16.mem"},p16);$readmemh({DATA_DIR,"/prob32.mem"},p32);$readmemh({DATA_DIR,"/v16.mem"},v16);$readmemh({DATA_DIR,"/v32.mem"},v32);$readmemh({DATA_DIR,"/e16.mem"},e16);$readmemh({DATA_DIR,"/e32.mem"},e32);repeat(8)@(posedge clk);rst_n<=1;end
 always@(negedge clk)if(rst_n)begin iv<=send<N;ordy<=!((cy%31)>=21&&(cy%31)<=25);end
 always@(posedge clk)if(rst_n)begin cy<=cy+1;if(iv&&ir)send<=send+1;if(err)begin $display("FAIL: M9 error");$finish;end;if(ov&&ordy)begin expected=CASE_ID==1?e16[recv]:e32[recv];for(lane=0;lane<16;lane=lane+1)begin got=out[lane*24+:24];exp=expected[lane*24+:24];diff=got-exp;if(diff<0)diff=-diff;errsum=errsum+diff;if(diff>maxerr)maxerr=diff;end if(out!==expected)mis<=mis+1;recv<=recv+1;c=cy-lastcy;if(c>maxrow)maxrow=c;lastcy=cy;if(recv==R-1)begin if(ic==N&&oc==R-1)begin $display("M9_PV_METRIC_JSON: {\"case\":\"%s\",\"rows\":32,\"keys\":4096,\"exact_row_mismatches\":%0d,\"mae_s24_lsb\":%0f,\"max_error_s24_lsb\":%0d,\"saturation_count\":%0d,\"max_row_cycles\":%0d,\"cycles\":%0d}",CASE_ID==1?"fp16":"fp32",mis+(out!==expected),errsum/512.0,maxerr,sc,c>maxrow?c:maxrow,cy);$display("PASS: M9 matched PV");end else $display("FAIL: M9 final");$finish;end end if(cy>300000)begin $display("FAIL: M9 timeout send=%0d recv=%0d",send,recv);$finish;end end
endmodule
